# Toy linear CH2-CH2 deck (the cluster PE runs' deck); its declaration digests are
# pinned by polymerSpecV2Test.  Structure and a declared MET block.
# MET transport: literature values, each field cited in transport_model.sources.
database(
    thermoLibraries=['primaryThermoLibrary'],
    reactionLibraries=[],
    seedMechanisms=[],
    kineticsDepositories='default',
    kineticsFamilies='default',
    kineticsEstimator='rate rules',
)
species(label='N2', reactive=False, structure=SMILES('N#N'))
